CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)ENGINE=InnoDB;
CREATE TABLE contracts(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,title VARCHAR(200) NOT NULL,contract_type VARCHAR(60) NOT NULL DEFAULT 'Other',parties VARCHAR(300),description TEXT,effective_date DATE NULL,expiry_date DATE NULL,renewal_terms VARCHAR(300),notice_period_days INT NULL,status ENUM('draft','under_review','active','expired','archived') NOT NULL DEFAULT 'draft',risk_level ENUM('unassessed','low','medium','high') NOT NULL DEFAULT 'unassessed',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,INDEX(user_id,status),INDEX(expiry_date))ENGINE=InnoDB;
CREATE TABLE contract_versions(id INT AUTO_INCREMENT PRIMARY KEY,contract_id INT NOT NULL,version_label VARCHAR(40) NOT NULL DEFAULT 'v1',original_name VARCHAR(255),stored_name CHAR(40) NOT NULL UNIQUE,sha256 CHAR(64) NOT NULL,mime VARCHAR(100),size_bytes INT,extracted_text LONGTEXT,extraction_method VARCHAR(40),extraction_status ENUM('success','empty','failed','manual') NOT NULL,extraction_error VARCHAR(300),word_count INT DEFAULT 0,uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(contract_id) REFERENCES contracts(id) ON DELETE RESTRICT)ENGINE=InnoDB;
CREATE TABLE analysis_results(id INT AUTO_INCREMENT PRIMARY KEY,contract_id INT NOT NULL,version_id INT NOT NULL,provider VARCHAR(60),summary_json LONGTEXT,status ENUM('success','error') NOT NULL,error_message VARCHAR(300),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(contract_id) REFERENCES contracts(id),FOREIGN KEY(version_id) REFERENCES contract_versions(id))ENGINE=InnoDB;
CREATE TABLE clauses(id INT AUTO_INCREMENT PRIMARY KEY,contract_id INT NOT NULL,version_id INT NOT NULL,category VARCHAR(60),text_excerpt TEXT,method VARCHAR(40) DEFAULT 'heuristic',FOREIGN KEY(contract_id) REFERENCES contracts(id),FOREIGN KEY(version_id) REFERENCES contract_versions(id))ENGINE=InnoDB;
CREATE TABLE risk_findings(id INT AUTO_INCREMENT PRIMARY KEY,contract_id INT NOT NULL,pillar ENUM('financial','termination','privacy','ip') NOT NULL,level ENUM('low','medium','high') NOT NULL,explanation TEXT,evidence TEXT,review_status ENUM('open','accepted','dismissed') DEFAULT 'open',FOREIGN KEY(contract_id) REFERENCES contracts(id))ENGINE=InnoDB;
CREATE TABLE obligation_suggestions(id INT AUTO_INCREMENT PRIMARY KEY,contract_id INT NOT NULL,description TEXT,responsible_party VARCHAR(150),due_date DATE NULL,trigger_text VARCHAR(200),source_text TEXT,extraction_method VARCHAR(40),review_status ENUM('pending','confirmed','rejected') DEFAULT 'pending',FOREIGN KEY(contract_id) REFERENCES contracts(id))ENGINE=InnoDB;
CREATE TABLE obligations(id INT AUTO_INCREMENT PRIMARY KEY,contract_id INT NOT NULL,suggestion_id INT NULL,description VARCHAR(500) NOT NULL,responsible_party VARCHAR(150),due_date DATE NULL,priority ENUM('low','medium','high') DEFAULT 'medium',status ENUM('pending','in_progress','completed','cancelled') DEFAULT 'pending',notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(contract_id) REFERENCES contracts(id) ON DELETE RESTRICT,INDEX(due_date,status))ENGINE=InnoDB;
CREATE TABLE payments(id INT AUTO_INCREMENT PRIMARY KEY,contract_id INT NOT NULL,expected_amount DECIMAL(14,2) NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'INR',due_date DATE NOT NULL,paid_amount DECIMAL(14,2) NULL,paid_date DATE NULL,status ENUM('pending','paid','partial') DEFAULT 'pending',notes VARCHAR(300),FOREIGN KEY(contract_id) REFERENCES contracts(id) ON DELETE RESTRICT,INDEX(due_date))ENGINE=InnoDB;
CREATE TABLE reminders(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,contract_id INT NOT NULL,kind VARCHAR(30) NOT NULL,ref_id INT NOT NULL DEFAULT 0,remind_on DATE NOT NULL,UNIQUE KEY uq(user_id,kind,ref_id,remind_on),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(contract_id) REFERENCES contracts(id))ENGINE=InnoDB;
CREATE TABLE notifications(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,message VARCHAR(300) NOT NULL,is_read TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id))ENGINE=InnoDB;
CREATE TABLE review_notes(id INT AUTO_INCREMENT PRIMARY KEY,contract_id INT NOT NULL,user_id INT NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(contract_id) REFERENCES contracts(id),FOREIGN KEY(user_id) REFERENCES users(id))ENGINE=InnoDB;
CREATE TABLE review_checklist_items(id INT AUTO_INCREMENT PRIMARY KEY,contract_id INT NOT NULL,label VARCHAR(200) NOT NULL,done TINYINT(1) DEFAULT 0,FOREIGN KEY(contract_id) REFERENCES contracts(id))ENGINE=InnoDB;
CREATE TABLE chat_messages(id INT AUTO_INCREMENT PRIMARY KEY,contract_id INT NOT NULL,user_id INT NOT NULL,role ENUM('user','assistant') NOT NULL,body TEXT NOT NULL,sources_json TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(contract_id) REFERENCES contracts(id),FOREIGN KEY(user_id) REFERENCES users(id))ENGINE=InnoDB;
CREATE TABLE activity_logs(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,contract_id INT NULL,action VARCHAR(80) NOT NULL,detail VARCHAR(300),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),INDEX(user_id,created_at))ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS contract_comparisons(id INT AUTO_INCREMENT PRIMARY KEY,contract_id INT NOT NULL,old_version_id INT NOT NULL,new_version_id INT NOT NULL,added_count INT NOT NULL,removed_count INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(contract_id) REFERENCES contracts(id) ON DELETE RESTRICT,FOREIGN KEY(old_version_id) REFERENCES contract_versions(id),FOREIGN KEY(new_version_id) REFERENCES contract_versions(id))ENGINE=InnoDB;
